-- Generated by scripts/migration/generate-schema.mjs from schema-map.mjs. Do not edit by hand.
-- AIC operational schema (Sheets → PostgreSQL migration, plan §2).

create schema if not exists aic;
revoke all on schema aic from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on schema aic from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on schema aic from authenticated'; end if;
  if not exists (select 1 from pg_roles where rolname = 'aic_app') then create role aic_app nologin; end if;
end $$;
grant usage on schema aic to aic_app;

-- Audit stamping. The app sets the actor per transaction:  select set_config('aic.actor', '<userId>', true);
-- Background jobs use 'system:<job>'. Writes without an actor fail. The importer (not aic_app) may set
-- aic.importing = 'on' to keep source audit values exactly as captured (null where the Sheet had none).
create or replace function aic.audit_stamp() returns trigger language plpgsql as $$
declare actor text := nullif(current_setting('aic.actor', true), '');
begin
  if current_setting('aic.importing', true) = 'on' and current_user <> 'aic_app' then return new; end if;
  if actor is null then raise exception 'aic.actor is not set for this transaction' using errcode = 'P0001'; end if;
  if tg_op = 'INSERT' then
    new.created_at := now(); new.created_by := actor; new.source_row := null; new.import_raw := null;
  else
    new.created_at := old.created_at; new.created_by := old.created_by;
    new.source_row := old.source_row; new.import_raw := old.import_raw;
  end if;
  new.updated_at := now(); new.updated_by := actor;
  return new;
end $$;

-- One row per import run: snapshot identity, counts and the validation report (no record contents).
create table if not exists aic.import_batches (
  batch_id text primary key, snapshot_sha256 text not null, captured_at timestamptz not null,
  started_at timestamptz not null default now(), promoted_at timestamptz, counts jsonb, report jsonb,
  source_row integer, import_raw jsonb, created_by text, created_at timestamptz, updated_by text, updated_at timestamptz
);

