create index on aic.sales_orders (received_date desc);
create index on aic.fti_requests (status);
create index on aic.liquidations (status);
create index on aic.document_handovers (document_type, document_number);

grant select, insert, update, delete on all tables in schema aic to aic_app;
revoke all on aic.import_batches from aic_app;
grant select on aic.import_batches to aic_app;
alter default privileges in schema aic grant select, insert, update, delete on tables to aic_app;
